CREATE OR REPLACE FUNCTION public.staff_tier(_user_id uuid) RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
SELECT CASE WHEN public.is_site_owner(_user_id) THEN -2 WHEN public.has_role(_user_id,'admin') THEN -1
ELSE coalesce((SELECT min(r.sort) FROM public.user_staff_roles u JOIN public.staff_roles r ON r.id=u.role_id WHERE u.user_id=_user_id),1000000000) END $$;
GRANT EXECUTE ON FUNCTION public.staff_tier(uuid) TO authenticated, service_role;
CREATE POLICY "tier roles insert" ON public.staff_roles AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (sort > public.staff_tier(auth.uid()));
CREATE POLICY "tier roles update" ON public.staff_roles AS RESTRICTIVE FOR UPDATE TO authenticated USING (sort > public.staff_tier(auth.uid())) WITH CHECK (sort > public.staff_tier(auth.uid()));
CREATE POLICY "tier roles delete" ON public.staff_roles AS RESTRICTIVE FOR DELETE TO authenticated USING (sort > public.staff_tier(auth.uid()));
CREATE POLICY "tier assign insert" ON public.user_staff_roles AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (public.staff_tier(user_id) > public.staff_tier(auth.uid()) AND (SELECT sort FROM public.staff_roles WHERE id=role_id) > public.staff_tier(auth.uid()));
CREATE POLICY "tier assign update" ON public.user_staff_roles AS RESTRICTIVE FOR UPDATE TO authenticated USING (public.staff_tier(user_id) > public.staff_tier(auth.uid())) WITH CHECK (public.staff_tier(user_id) > public.staff_tier(auth.uid()) AND (SELECT sort FROM public.staff_roles WHERE id=role_id) > public.staff_tier(auth.uid()));
CREATE POLICY "tier assign delete" ON public.user_staff_roles AS RESTRICTIVE FOR DELETE TO authenticated USING (public.staff_tier(user_id) > public.staff_tier(auth.uid()) AND (SELECT sort FROM public.staff_roles WHERE id=role_id) > public.staff_tier(auth.uid()));
CREATE OR REPLACE FUNCTION public.my_permissions() RETURNS text[] LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
SELECT CASE WHEN public.is_account_banned(auth.uid()) THEN '{}'::text[] WHEN public.is_site_owner(auth.uid()) OR public.has_role(auth.uid(),'admin') THEN ARRAY['players.view','players.profile','players.tokens','players.password_reset','players.delete','players.ban','players.inventory','logs.view','shop','blooks','games','missions','chat','roles','badges'] || CASE WHEN public.has_permission(auth.uid(),'ips.view') THEN ARRAY['ips.view'] ELSE '{}'::text[] END ELSE coalesce((SELECT array_agg(DISTINCT p) FROM public.user_staff_roles u JOIN public.staff_roles r ON r.id=u.role_id,unnest(r.permissions) p WHERE u.user_id=auth.uid() AND p<>'users'),'{}') END $$;